public class Main {
    static int[][] kClosest(int[][] points, int k) {
        int[][] sorted = points.clone();
        Arrays.sort(sorted, (a, b) -> (a[0]*a[0] + a[1]*a[1]) - (b[0]*b[0] + b[1]*b[1]));  // sort ALL points
        return Arrays.copyOfRange(sorted, 0, k);
    }
}

