import heapq

def k_closest(points, k):
    heap = []                                # max-heap via negated distance
    for x, y in points:
        dist = x * x + y * y
        heapq.heappush(heap, (-dist, x, y))
        if len(heap) > k:
            heapq.heappop(heap)               # remove the farthest, no longer in the top k
    return [[x, y] for _, x, y in heap]

